(window.DSR_SUBJECTS=window.DSR_SUBJECTS||{})["DPL302"]={"code": "DPL302", "name": "Deep Learning", "topics": ["Neural Networks cơ bản", "Regularization & tối ưu hoá", "Siêu tham số & Batch Norm", "Chiến lược ML", "CNN cơ bản", "Kiến trúc CNN & transfer", "Detection, segmentation & face", "RNN, GRU & LSTM", "Embedding, attention & Transformer"], "q": [{"id": 0, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 281, "x": "RNN một chiều chỉ dùng thông tin từ các từ trước. Ở vị trí 'Teddy' nó chưa thấy 'Roosevelt' hay 'bears' nên không biết đây là tên người hay không.", "tip": "Cần nhìn cả phía sau → bidirectional RNN.", "img": "data:image/webp;base64,"}, {"id": 1, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 335, "x": "Lượt lan truyền ngược đi từ bước cuối về bước đầu, tức là ngược chiều thời gian.", "tip": "Through time = đi ngược trục thời gian.", "img": "data:image/webp;base64,"}, {"id": 2, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 382, "x": "Phân loại cảm xúc đọc cả câu (nhiều đầu vào) và cho ra một nhãn → many-to-one.", "tip": "Nhiều từ vào, 1 điểm sao ra.", "img": "data:image/webp;base64,"}, {"id": 3, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1137, "h": 403, "x": "Sinh nhạc: một đầu vào (thể loại hoặc rỗng) sinh ra cả chuỗi nốt → one-to-many.", "tip": "1 hạt giống, ra cả bản nhạc.", "img": "data:image/webp;base64,"}, {"id": 4, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 378, "x": "NER gắn nhãn cho từng từ, số đầu ra bằng số đầu vào → many-to-many với Tx = Ty.", "tip": "Mỗi từ một nhãn → độ dài bằng nhau.", "img": "data:image/webp;base64,"}, {"id": 5, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 418, "x": "Dịch máy: câu nguồn và câu đích dài khác nhau → many-to-many Tx ≠ Ty, kiến trúc encoder–decoder.", "tip": "Dịch = encoder đọc hết rồi decoder viết.", "img": "data:image/webp;base64,"}, {"id": 6, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 400, "x": "Mô hình ngôn ngữ ước lượng xác suất của cả câu P(y⟨1⟩,…,y⟨Ty⟩).", "tip": "Language model = xác suất câu.", "img": "data:image/webp;base64,"}, {"id": 7, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1069, "h": 521, "x": "⟨EOS⟩ đánh dấu kết thúc câu để mô hình biết khi nào dừng.", "tip": "EOS = End Of Sentence.", "img": "data:image/webp;base64,"}, {"id": 8, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 295, "x": "Khi huấn luyện, đầu vào bước t là từ đúng ở bước trước y⟨t−1⟩ (teacher forcing).", "tip": "Đưa đáp án bước trước làm input bước sau.", "img": "data:image/webp;base64,"}, {"id": 9, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 274, "x": "Lấy mẫu ngẫu nhiên một từ theo phân phối softmax ŷ⟨t⟩ rồi đưa từ đó làm input bước kế tiếp.", "tip": "Sampling = np.random.choice theo xác suất.", "img": "data:image/webp;base64,"}, {"id": 10, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 346, "x": "Mô hình mức ký tự ghép được mọi từ từ ký tự nên không bao giờ gặp từ lạ, không cần ⟨UNK⟩.", "tip": "Ký tự thì từ nào cũng ghép được.", "img": "data:image/webp;base64,"}, {"id": 11, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 274, "x": "Chuỗi ký tự dài hơn nhiều so với chuỗi từ nên khó nắm phụ thuộc xa và tốn chi phí huấn luyện.", "tip": "Dài hơn → khó nhớ xa + đắt hơn.", "img": "data:image/webp;base64,"}, {"id": 12, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 326, "x": "Gradient bùng nổ được xử lý bằng gradient clipping: co gradient lại khi vượt ngưỡng.", "tip": "Exploding → clip; vanishing → GRU/LSTM.", "img": "data:image/webp;base64,"}, {"id": 13, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 270, "x": "Nhớ 'cat' qua nhiều từ để chia động từ 'was' là phụ thuộc xa; RNN cơ bản gặp vanishing gradient nên khó học.", "tip": "Phụ thuộc xa = vanishing gradient.", "img": "data:image/webp;base64,"}, {"id": 14, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 297, "x": "Trong GRU, ô nhớ và activation là một: c⟨t⟩ = a⟨t⟩. LSTM mới tách riêng hai đại lượng này.", "tip": "GRU: c = a; LSTM: c ≠ a.", "img": "data:image/webp;base64,"}, {"id": 15, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 312, "x": "Γu ≈ 0 thì c⟨t⟩ ≈ c⟨t−1⟩: giữ nguyên ô nhớ, gradient truyền xa được nên đỡ vanishing.", "tip": "Cổng cập nhật đóng = giữ trí nhớ.", "img": "data:image/webp;base64,"}, {"id": 16, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 364, "x": "Cổng relevance Γr quyết định c⟨t−1⟩ liên quan bao nhiêu khi tính ứng viên c̃⟨t⟩.", "tip": "r = relevance (độ liên quan).", "img": "data:image/webp;base64,"}, {"id": 17, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1165, "h": 490, "x": "LSTM có 3 cổng: update (input), forget, output.", "tip": "LSTM = I-F-O.", "img": "data:image/webp;base64,"}, {"id": 18, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 281, "x": "GRU đơn giản và nhanh hơn (2 cổng); LSTM mạnh hơn (3 cổng) và từ lâu là lựa chọn mặc định đầu tiên.", "tip": "GRU nhẹ, LSTM mạnh.", "img": "data:image/webp;base64,"}, {"id": 19, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 284, "x": "BRNN cần cả câu rồi mới dự đoán nên không hợp nhận dạng giọng nói thời gian thực.", "tip": "Hai chiều → phải chờ hết câu.", "img": "data:image/webp;base64,"}, {"id": 20, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 294, "x": "Transformer xử lý cả chuỗi song song thay vì tuần tự từng từ như RNN.", "tip": "Transformer = song song.", "img": "data:image/webp;base64,"}, {"id": 21, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 252, "x": "Các vector one-hot đôi một vuông góc nên mô hình không biết 'apple' gần 'orange', không tổng quát hoá được.", "tip": "One-hot: mọi từ cách đều nhau.", "img": "data:image/webp;base64,"}, {"id": 22, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 242, "x": "Word embedding điển hình trong khoá học có 300 chiều.", "tip": "Nhớ con số 300.", "img": "data:image/webp;base64,"}, {"id": 23, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 255, "x": "A⟨t⟩ = tổng có trọng số các value v⟨i⟩, trọng số là softmax của q⟨t⟩·k⟨i⟩.", "tip": "Query hỏi, Key trả lời, Value được cộng lại.", "img": "data:image/webp;base64,"}, {"id": 24, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 288, "x": "Học embedding trên corpus lớn (hoặc tải sẵn) → dùng cho task nhỏ → fine-tune nếu đủ dữ liệu.", "tip": "Lớn → nhỏ → (tuỳ chọn) tinh chỉnh.", "img": "data:image/webp;base64,"}, {"id": 25, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 249, "x": "Embedding sẵn ít có ích khi task đã có rất nhiều dữ liệu, như language modeling hay dịch máy.", "tip": "Nhiều dữ liệu riêng thì cần transfer ít.", "img": "data:image/webp;base64,"}, {"id": 26, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 276, "x": "Tìm từ w có e_w gần nhất với e_king − e_man + e_woman, cho ra 'queen'.", "tip": "King − man + woman = queen.", "img": "data:image/webp;base64,"}, {"id": 27, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 276, "x": "Hai vector cùng hướng có góc 0°, cos 0° = 1.", "tip": "Cùng hướng 1, vuông góc 0, ngược hướng −1.", "img": "data:image/webp;base64,"}, {"id": 28, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 289, "x": "Nhân E với one-hot O_j chọn ra đúng cột j, tức embedding e_j (300×1).", "tip": "One-hot nhân ma trận = lấy cột.", "img": "data:image/webp;base64,"}, {"id": 29, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 307, "x": "Thực tế tra trực tiếp cột (Embedding layer) vì nhân ma trận với one-hot rất phí.", "tip": "Lookup thay vì nhân.", "img": "data:image/webp;base64,"}, {"id": 30, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 300, "x": "4 từ × 300 chiều = 1200 chiều sau khi nối.", "tip": "Số từ × số chiều.", "img": "data:image/webp;base64,"}, {"id": 31, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 276, "x": "Skip-gram chọn từ context rồi dự đoán từ target trong một cửa sổ quanh nó.", "tip": "Skip-gram: 1 từ → đoán hàng xóm.", "img": "data:image/webp;base64,"}, {"id": 32, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 288, "x": "Mẫu số softmax phải cộng qua cả từ điển (10.000+ từ) nên rất chậm.", "tip": "Softmax lớn = mẫu số khổng lồ.", "img": "data:image/webp;base64,"}, {"id": 33, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 296, "x": "Chia √d_k để tích vô hướng không quá lớn, tránh softmax bão hoà và gradient bất ổn.", "tip": "Scaled = chia √d_k cho ổn định.", "img": "data:image/webp;base64,"}, {"id": 34, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 375, "x": "CBOW dùng các từ xung quanh để đoán từ ở giữa (ngược với skip-gram).", "tip": "CBOW: hàng xóm → từ giữa.", "img": "data:image/webp;base64,"}, {"id": 35, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 375, "x": "k = 5–20 cho tập nhỏ, 2–5 cho tập lớn.", "tip": "Dữ liệu càng lớn, k càng nhỏ.", "img": "data:image/webp;base64,"}, {"id": 36, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 246, "x": "Mỗi bước chỉ cập nhật k+1 bộ phân loại nhị phân thay vì softmax 10.000 lớp.", "tip": "Negative sampling = vài sigmoid thay vì một softmax lớn.", "img": "data:image/webp;base64,"}, {"id": 37, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 288, "x": "Multi-head attention gồm nhiều head self-attention, mỗi head có W^Q, W^K, W^V riêng, chạy song song.", "tip": "Mỗi head hỏi một câu hỏi khác.", "img": "data:image/webp;base64,"}, {"id": 38, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 333, "x": "X_ij là số lần từ i xuất hiện trong ngữ cảnh của từ j.", "tip": "GloVe = Global Vectors từ ma trận đồng xuất hiện.", "img": "data:image/webp;base64,"}, {"id": 39, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 240, "x": "Transformer cộng positional encoding (sin/cos) vào embedding để biết thứ tự từ.", "tip": "Không có RNN → cần positional encoding.", "img": "data:image/webp;base64,"}, {"id": 40, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 351, "x": "Trong GloVe, θ_w và e_w đối xứng nên embedding cuối là trung bình (e_w + θ_w)/2.", "tip": "GloVe: lấy trung bình hai vector.", "img": "data:image/webp;base64,"}, {"id": 41, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 289, "x": "Mô hình trung bình bỏ qua thứ tự từ; nhiều chữ 'good' làm câu chê trông như khen.", "tip": "Trung bình mất trật tự → dùng RNN.", "img": "data:image/webp;base64,"}, {"id": 42, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 256, "x": "Debias: xác định hướng bias → neutralize → equalize các cặp.", "tip": "Identify → Neutralize → Equalize.", "img": "data:image/webp;base64,"}, {"id": 43, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 283, "x": "Chỉ neutralize các từ không mang nghĩa giới tính theo định nghĩa (doctor, babysitter).", "tip": "Grandmother/grandfather thì equalize, không neutralize.", "img": "data:image/webp;base64,"}, {"id": 44, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 271, "x": "Decoder ước lượng P(y | x), khởi đầu từ output encoder thay vì vector 0, nên là language model có điều kiện.", "tip": "Conditional = có điều kiện x.", "img": "data:image/webp;base64,"}, {"id": 45, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 282, "x": "Greedy chọn từ tốt nhất từng bước nên có thể dẫn tới cả câu tệ hơn.", "tip": "Tốt từng bước ≠ tốt cả câu.", "img": "data:image/webp;base64,"}, {"id": 46, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 425, "x": "Beam width B = 1 chỉ giữ một ứng viên → chính là greedy search.", "tip": "B = 1 = greedy.", "img": "data:image/webp;base64,"}, {"id": 47, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 239, "x": "Masked attention che các từ đích phía sau để mô hình không nhìn trước khi dự đoán trái sang phải.", "tip": "Mask = cấm nhìn tương lai.", "img": "data:image/webp;base64,"}, {"id": 48, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 282, "x": "Cộng log xác suất và chia cho Ty^α (α ≈ 0.7) để giảm thiên vị câu ngắn.", "tip": "Chuẩn hoá theo độ dài câu.", "img": "data:image/webp;base64,"}, {"id": 49, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 243, "x": "P(y*|x) > P(ŷ|x) mà beam vẫn chọn ŷ → beam search có lỗi, nên tăng B.", "tip": "y* tốt hơn mà không được chọn → lỗi beam.", "img": "data:image/webp;base64,"}, {"id": 50, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 267, "x": "'the' xuất hiện tối đa 2 lần trong một reference nên được tính 2/7.", "tip": "Clip theo số lần tối đa trong reference.", "img": "data:image/webp;base64,"}, {"id": 51, "t": "Embedding, attention & Transformer", "a": "B", "n": 4, "w": 1200, "h": 399, "x": "Brevity penalty phạt bản dịch quá ngắn (vì câu ngắn dễ có precision cao).", "tip": "Brevity = ngắn gọn → phạt ngắn.", "img": "data:image/webp;base64,"}, {"id": 52, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 365, "x": "α⟨t,t'⟩ là mức chú ý output bước t dành cho từ input t'.", "tip": "α = trọng số chú ý.", "img": "data:image/webp;base64,"}, {"id": 53, "t": "Embedding, attention & Transformer", "a": "C", "n": 4, "w": 1200, "h": 360, "x": "Attention tốn chi phí bậc hai O(Tx × Ty).", "tip": "Mỗi output nhìn mọi input → nhân hai độ dài.", "img": "data:image/webp;base64,"}, {"id": 54, "t": "Embedding, attention & Transformer", "a": "A", "n": 4, "w": 1200, "h": 368, "x": "Add & Norm = residual connection rồi layer normalization.", "tip": "Add = cộng tắt, Norm = chuẩn hoá lớp.", "img": "data:image/webp;base64,"}, {"id": 55, "t": "Embedding, attention & Transformer", "a": "D", "n": 4, "w": 1200, "h": 252, "x": "Nhãn = 0 trước và trong lúc nói trigger word, rồi = 1 vài bước ngay sau khi nói xong.", "tip": "Bật 1 sau khi nói xong.", "img": "data:image/webp;base64,"}, {"id": 56, "t": "Siêu tham số & Batch Norm", "a": "B", "n": 4, "w": 1200, "h": 272, "x": "Không biết trước siêu tham số nào quan trọng; random thử được nhiều giá trị khác nhau của mỗi tham số hơn grid.", "tip": "Random > grid vì đa dạng giá trị.", "img": "data:image/webp;base64,"}, {"id": 57, "t": "Siêu tham số & Batch Norm", "a": "D", "n": 4, "w": 1173, "h": 352, "x": "Lấy mẫu trên thang log: r = −4·rand(), α = 10^r.", "tip": "Learning rate → thang log.", "img": "data:image/webp;base64,"}, {"id": 58, "t": "Siêu tham số & Batch Norm", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "β gần 1 rất nhạy, nên lấy mẫu 1 − β trên thang log trong [0.001, 0.1].", "tip": "Lấy mẫu 1 − β, không phải β.", "img": "data:image/webp;base64,"}, {"id": 59, "t": "Siêu tham số & Batch Norm", "a": "C", "n": 4, "w": 1200, "h": 296, "x": "Panda: chăm một mô hình, chỉnh mỗi ngày khi ít tài nguyên. Caviar: chạy nhiều mô hình song song.", "tip": "Panda ít con, Caviar nhiều trứng.", "img": "data:image/webp;base64,"}, {"id": 60, "t": "Siêu tham số & Batch Norm", "a": "B", "n": 4, "w": 1200, "h": 436, "x": "BatchNorm chuẩn hoá giá trị trung gian z^[l] của các lớp ẩn.", "tip": "BN chuẩn hoá z, không phải W.", "img": "data:image/webp;base64,"}, {"id": 61, "t": "Siêu tham số & Batch Norm", "a": "D", "n": 4, "w": 1200, "h": 240, "x": "γ và β là tham số học được để mạng tự chọn mean/variance của z.", "tip": "γ scale, β shift – đều học được.", "img": "data:image/webp;base64,"}, {"id": 62, "t": "Siêu tham số & Batch Norm", "a": "A", "n": 4, "w": 1200, "h": 297, "x": "Mean/variance tính theo mini-batch nên thêm nhiễu vào z → hiệu ứng regularization nhẹ.", "tip": "Nhiễu mini-batch ≈ dropout nhẹ.", "img": "data:image/webp;base64,"}, {"id": 63, "t": "Siêu tham số & Batch Norm", "a": "C", "n": 4, "w": 1200, "h": 223, "x": "Khi test, μ và σ² ước lượng bằng trung bình trọng số mũ qua các mini-batch huấn luyện.", "tip": "Test dùng running average.", "img": "data:image/webp;base64,"}, {"id": 64, "t": "Siêu tham số & Batch Norm", "a": "D", "n": 4, "w": 1200, "h": 288, "x": "e^5/(e^5+e^2+e^−1+e^3) ≈ 148.4/176.2 ≈ 0.842.", "tip": "Phần tử lớn nhất áp đảo softmax.", "img": "data:image/webp;base64,"}, {"id": 65, "t": "Siêu tham số & Batch Norm", "a": "B", "n": 4, "w": 1020, "h": 407, "x": "Softmax loss: L = −Σ y_j log ŷ_j (cross-entropy).", "tip": "Softmax đi với cross-entropy.", "img": "data:image/webp;base64,"}, {"id": 66, "t": "Chiến lược ML", "a": "A", "n": 4, "w": 1200, "h": 318, "x": "Orthogonalization: mỗi núm chỉnh chỉ tác động một khía cạnh của hiệu năng.", "tip": "Một núm, một việc.", "img": "data:image/webp;base64,"}, {"id": 67, "t": "Chiến lược ML", "a": "C", "n": 4, "w": 1200, "h": 257, "x": "Tốt trên dev mà kém trên test → đã overfit dev, cần dev lớn hơn.", "tip": "Dev ổn, test kém → tăng dev.", "img": "data:image/webp;base64,"}, {"id": 68, "t": "Chiến lược ML", "a": "B", "n": 4, "w": 1200, "h": 258, "x": "Precision = TP/(dự đoán dương) = 3/4.", "tip": "Precision: trong số bảo là mèo, đúng bao nhiêu.", "img": "data:image/webp;base64,"}, {"id": 69, "t": "Chiến lược ML", "a": "D", "n": 4, "w": 1061, "h": 395, "x": "F1 = trung bình điều hoà của precision và recall.", "tip": "F1 = 2PR/(P+R).", "img": "data:image/webp;base64,"}, {"id": 70, "t": "Chiến lược ML", "a": "A", "n": 4, "w": 1200, "h": 271, "x": "Trong các classifier chạy ≤ 100 ms (A, B), chọn cái chính xác nhất: B (92%). Đáp án A của câu ghi 'B'.", "tip": "Lọc theo ràng buộc trước, tối ưu sau.", "img": "data:image/webp;base64,"}, {"id": 71, "t": "Chiến lược ML", "a": "B", "n": 4, "w": 964, "h": 443, "x": "Avoidable bias = training error − human-level error (proxy Bayes).", "tip": "Bias tránh được = train − người.", "img": "data:image/webp;base64,"}, {"id": 72, "t": "Chiến lược ML", "a": "C", "n": 4, "w": 1200, "h": 271, "x": "Bias tránh được 0.5% (8 − 7.5) < variance 2% (10 − 8) → giảm variance.", "tip": "So hai khoảng cách, chọn cái lớn hơn.", "img": "data:image/webp;base64,"}, {"id": 73, "t": "Chiến lược ML", "a": "D", "n": 4, "w": 1200, "h": 273, "x": "Proxy Bayes error là mức tốt nhất đạt được: đội chuyên gia 0.5%.", "tip": "Bayes ≈ người giỏi nhất.", "img": "data:image/webp;base64,"}, {"id": 74, "t": "Chiến lược ML", "a": "A", "n": 4, "w": 1200, "h": 229, "x": "ML vượt người rõ ở bài toán dữ liệu có cấu trúc, nhiều dữ liệu (quảng cáo, duyệt vay).", "tip": "Structured + big data.", "img": "data:image/webp;base64,"}, {"id": 75, "t": "Chiến lược ML", "a": "C", "n": 4, "w": 1200, "h": 264, "x": "Sửa hết lỗi chó chỉ giảm 5% của 10% → còn 9.5%.", "tip": "Trần cải thiện = tỷ lệ × lỗi.", "img": "data:image/webp;base64,"}, {"id": 76, "t": "Chiến lược ML", "a": "B", "n": 4, "w": 1200, "h": 329, "x": "Deep learning khá chịu được nhãn sai ngẫu nhiên, nhưng không chịu được nhãn sai có hệ thống.", "tip": "Random ổn, systematic thì không.", "img": "data:image/webp;base64,"}, {"id": 77, "t": "Chiến lược ML", "a": "D", "n": 4, "w": 1200, "h": 248, "x": "Sửa dev thì sửa cả test để hai tập cùng phân phối.", "tip": "Dev và test luôn đi cùng nhau.", "img": "data:image/webp;base64,"}, {"id": 78, "t": "Chiến lược ML", "a": "A", "n": 4, "w": 1200, "h": 259, "x": "Dev/test chỉ dùng ảnh app (đích thật); train dùng ảnh web + 5.000 ảnh app.", "tip": "Dev/test phải giống dữ liệu thật.", "img": "data:image/webp;base64,"}, {"id": 79, "t": "Chiến lược ML", "a": "C", "n": 4, "w": 1200, "h": 277, "x": "Training-dev cùng phân phối train nhưng không train trên đó → tách variance khỏi data mismatch.", "tip": "Train-dev đo variance thuần.", "img": "data:image/webp;base64,"}, {"id": 80, "t": "Chiến lược ML", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "Train→train-dev chỉ tăng 0.5% (variance thấp), train-dev→dev tăng 8.5% → data mismatch.", "tip": "Khoảng cách lớn nhất nằm ở đâu.", "img": "data:image/webp;base64,"}, {"id": 81, "t": "Chiến lược ML", "a": "D", "n": 4, "w": 1200, "h": 270, "x": "Transfer A→B hợp lý khi cùng kiểu input và A có nhiều dữ liệu hơn B.", "tip": "Học từ việc lớn sang việc nhỏ.", "img": "data:image/webp;base64,"}, {"id": 82, "t": "Chiến lược ML", "a": "B", "n": 4, "w": 1200, "h": 278, "x": "Một ảnh có thể có nhiều đối tượng → 4 sigmoid độc lập, không dùng softmax.", "tip": "Multi-label → sigmoid.", "img": "data:image/webp;base64,"}, {"id": 83, "t": "Chiến lược ML", "a": "C", "n": 4, "w": 1200, "h": 294, "x": "End-to-end cần đủ dữ liệu để học trực tiếp ánh xạ phức tạp x → y.", "tip": "End-to-end ăn nhiều dữ liệu.", "img": "data:image/webp;base64,"}, {"id": 85, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 281, "x": "Input 3 triệu chiều × 1000 unit = 3 tỷ tham số.", "tip": "FC trên ảnh lớn bùng nổ tham số → dùng CNN.", "img": "data:image/webp;base64,"}, {"id": 86, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 1200, "h": 264, "x": "Parameter sharing: một bộ lọc hữu ích ở một vùng ảnh cũng hữu ích ở vùng khác, nên dùng chung trọng số.", "tip": "Một filter quét cả ảnh.", "img": "data:image/webp;base64,"}, {"id": 87, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 1200, "h": 270, "x": "Mỗi giá trị output chỉ phụ thuộc vào một vùng nhỏ f×f của input.", "tip": "Sparse = mỗi output nhìn vùng nhỏ.", "img": "data:image/webp;base64,"}, {"id": 88, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 925, "h": 444, "x": "[[1,0,−1],[1,0,−1],[1,0,−1]]: sáng bên trái, tối bên phải → phát hiện cạnh dọc.", "tip": "Cột 1 / 0 / −1 = cạnh dọc.", "img": "data:image/webp;base64,"}, {"id": 89, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1200, "h": 281, "x": "n − f + 1 = 6 − 3 + 1 = 4 → 4×4.", "tip": "Không padding: n − f + 1.", "img": "data:image/webp;base64,"}, {"id": 90, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 943, "h": 448, "x": "Sobel: [[1,0,−1],[2,0,−2],[1,0,−1]] (hàng giữa trọng số 2). Scharr là 3/10/3.", "tip": "Sobel 1-2-1, Scharr 3-10-3.", "img": "data:image/webp;base64,"}, {"id": 91, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 303, "x": "Coi giá trị filter là tham số và học bằng backprop.", "tip": "Deep learning: học filter, không tự thiết kế.", "img": "data:image/webp;base64,"}, {"id": 92, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1200, "h": 328, "x": "Thứ deep learning gọi là 'convolution' thực chất là cross-correlation (không lật filter).", "tip": "Không flip = cross-correlation.", "img": "data:image/webp;base64,"}, {"id": 93, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 1200, "h": 235, "x": "Padding chống ảnh co lại sau mỗi lớp và giúp dùng điểm ảnh ở viền nhiều hơn.", "tip": "Padding: giữ kích thước + giữ viền.", "img": "data:image/webp;base64,"}, {"id": 94, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 1200, "h": 307, "x": "'Same' cần p = (f − 1)/2 để output bằng input.", "tip": "f = 3 → p = 1; f = 5 → p = 2.", "img": "data:image/webp;base64,"}, {"id": 95, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 327, "x": "f lẻ cho phép padding đối xứng và có điểm ảnh trung tâm.", "tip": "Lẻ thì có tâm.", "img": "data:image/webp;base64,"}, {"id": 96, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 1200, "h": 239, "x": "⌊(7 − 3)/2⌋ + 1 = 3 → 3×3.", "tip": "Công thức ⌊(n + 2p − f)/s⌋ + 1.", "img": "data:image/webp;base64,"}, {"id": 97, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1163, "h": 341, "x": "⌊(100 + 14 − 6)/4⌋ + 1 = 27 + 1 = 28 → 28×28.", "tip": "Nhớ cộng 2p trước khi chia s.", "img": "data:image/webp;base64,"}, {"id": 98, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 1200, "h": 276, "x": "Mỗi filter phải có số kênh bằng số kênh input (RGB = 3).", "tip": "Kênh filter = kênh input.", "img": "data:image/webp;base64,"}, {"id": 99, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 262, "x": "6 − 3 + 1 = 4, hai filter → 4×4×2.", "tip": "Số filter = số kênh output.", "img": "data:image/webp;base64,"}, {"id": 100, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1200, "h": 230, "x": "Mỗi filter 3×3×3 = 27 trọng số + 1 bias = 28; × 10 = 280.", "tip": "Đừng quên bias.", "img": "data:image/webp;base64,"}, {"id": 101, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 1181, "h": 376, "x": "Trọng số lớp l: f × f × n_c^[l−1] × n_c^[l].", "tip": "Kích thước filter × kênh vào × số filter.", "img": "data:image/webp;base64,"}, {"id": 102, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 1200, "h": 264, "x": "39 − 3 + 1 = 37 → 37×37×10.", "tip": "n − f + 1 với p = 0, s = 1.", "img": "data:image/webp;base64,"}, {"id": 103, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 288, "x": "Càng sâu thì chiều cao/rộng giảm, số kênh tăng.", "tip": "Ảnh nhỏ dần, dày dần.", "img": "data:image/webp;base64,"}, {"id": 104, "t": "CNN cơ bản", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "⌊(4 − 2)/2⌋ + 1 = 2 → 2×2.", "tip": "Pool 2/2 chia đôi kích thước.", "img": "data:image/webp;base64,"}, {"id": 105, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1200, "h": 338, "x": "Pooling không có tham số học, chỉ có siêu tham số f và s.", "tip": "Pooling = 0 tham số.", "img": "data:image/webp;base64,"}, {"id": 106, "t": "CNN cơ bản", "a": "D", "n": 4, "w": 1200, "h": 274, "x": "Pooling áp dụng riêng từng kênh nên số kênh không đổi.", "tip": "Pool không đổi n_c.", "img": "data:image/webp;base64,"}, {"id": 107, "t": "CNN cơ bản", "a": "B", "n": 4, "w": 1200, "h": 279, "x": "Mỗi filter 5×5×3 = 75 + 1 bias = 76; × 6 = 456.", "tip": "(f·f·n_c + 1) × số filter.", "img": "data:image/webp;base64,"}, {"id": 108, "t": "CNN cơ bản", "a": "C", "n": 4, "w": 1200, "h": 300, "x": "Phần lớn tham số của LeNet-5 nằm ở các lớp fully connected.", "tip": "FC mới là chỗ tốn tham số.", "img": "data:image/webp;base64,"}, {"id": 109, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 277, "x": "LeNet-5 (LeCun 1998): input 32×32×1, khoảng 60K tham số.", "tip": "LeNet = 60 nghìn.", "img": "data:image/webp;base64,"}, {"id": 110, "t": "Kiến trúc CNN & transfer", "a": "B", "n": 4, "w": 1200, "h": 376, "x": "AlexNet có khoảng 60M tham số và phổ biến ReLU.", "tip": "AlexNet = 60 triệu + ReLU.", "img": "data:image/webp;base64,"}, {"id": 111, "t": "Kiến trúc CNN & transfer", "a": "D", "n": 4, "w": 1200, "h": 267, "x": "VGG-16: toàn conv 3×3 same và max-pool 2×2, khoảng 138M tham số.", "tip": "VGG = đồng đều 3×3, 138M.", "img": "data:image/webp;base64,"}, {"id": 112, "t": "Kiến trúc CNN & transfer", "a": "C", "n": 4, "w": 1200, "h": 467, "x": "Residual: a^[l+2] = g(z^[l+2] + a^[l]).", "tip": "Cộng a^[l] trước khi qua activation.", "img": "data:image/webp;base64,"}, {"id": 113, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 300, "x": "Khi W, b ≈ 0 thì block dễ học hàm đồng nhất nên thêm block hiếm khi làm tệ đi.", "tip": "Residual dễ học identity.", "img": "data:image/webp;base64,"}, {"id": 114, "t": "Kiến trúc CNN & transfer", "a": "D", "n": 4, "w": 1200, "h": 321, "x": "Khác chiều thì nhân a^[l] với ma trận W_s cho khớp.", "tip": "Chiều lệch → W_s.", "img": "data:image/webp;base64,"}, {"id": 115, "t": "Kiến trúc CNN & transfer", "a": "B", "n": 4, "w": 1200, "h": 308, "x": "Conv 1×1 dùng để giảm (hoặc đổi) số kênh, ví dụ 192 → 32.", "tip": "1×1 = co kênh.", "img": "data:image/webp;base64,"}, {"id": 116, "t": "Kiến trúc CNN & transfer", "a": "C", "n": 4, "w": 1200, "h": 276, "x": "28·28·32 output × (5·5·192) phép nhân ≈ 120 triệu.", "tip": "Output × kích thước filter.", "img": "data:image/webp;base64,"}, {"id": 117, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "Bottleneck: 28·28·16·192 ≈ 2.4M + 28·28·32·(5·5·16) ≈ 10M → khoảng 12.4M.", "tip": "Bottleneck giảm khoảng 10 lần.", "img": "data:image/webp;base64,"}, {"id": 118, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 272, "x": "Nhánh phụ của Inception dự đoán từ lớp giữa, giúp regularize.", "tip": "Side branch = regularization.", "img": "data:image/webp;base64,"}, {"id": 119, "t": "Kiến trúc CNN & transfer", "a": "D", "n": 4, "w": 1200, "h": 338, "x": "MobileNet thay conv thường bằng depthwise separable (depthwise + pointwise).", "tip": "Depthwise rồi pointwise.", "img": "data:image/webp;base64,"}, {"id": 120, "t": "Kiến trúc CNN & transfer", "a": "C", "n": 4, "w": 1200, "h": 276, "x": "Thường: 4·4·5·(3·3·3) = 2160. Depthwise 4·4·3·9 = 432 + pointwise 4·4·5·3 = 240 → 672.", "tip": "Separable rẻ hơn khoảng 3 lần ở ví dụ này.", "img": "data:image/webp;base64,"}, {"id": 121, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 249, "x": "MobileNet v2 bottleneck: expansion 1×1 → depthwise → projection 1×1, có residual.", "tip": "Mở rộng → depthwise → thu hẹp.", "img": "data:image/webp;base64,"}, {"id": 122, "t": "Kiến trúc CNN & transfer", "a": "D", "n": 4, "w": 1200, "h": 252, "x": "EfficientNet co giãn đồng thời độ phân giải, độ sâu, độ rộng theo ngân sách tính toán.", "tip": "Compound scaling.", "img": "data:image/webp;base64,"}, {"id": 123, "t": "Kiến trúc CNN & transfer", "a": "B", "n": 4, "w": 1200, "h": 246, "x": "Rất ít dữ liệu → đóng băng toàn bộ lớp pretrained, chỉ huấn luyện softmax mới.", "tip": "Ít data → freeze nhiều.", "img": "data:image/webp;base64,"}, {"id": 124, "t": "Kiến trúc CNN & transfer", "a": "C", "n": 4, "w": 1200, "h": 245, "x": "Color shifting cộng/trừ giá trị R, G, B để bền với thay đổi ánh sáng.", "tip": "Đổi màu để chống ánh sáng.", "img": "data:image/webp;base64,"}, {"id": 125, "t": "Kiến trúc CNN & transfer", "a": "A", "n": 4, "w": 1200, "h": 256, "x": "Ensembling và multi-crop chủ yếu để thắng benchmark, ít dùng khi triển khai thật.", "tip": "Tốn tính toán → chỉ dùng thi đấu.", "img": "data:image/webp;base64,"}, {"id": 126, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1200, "h": 256, "x": "b_x, b_y là tâm; b_h, b_w là chiều cao, rộng bounding box.", "tip": "x, y = tâm; h, w = kích thước.", "img": "data:image/webp;base64,"}, {"id": 127, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1200, "h": 332, "x": "Không có vật thể: p_c = 0, các phần tử còn lại 'không quan tâm' (?).", "tip": "p_c = 0 thì phần còn lại bỏ qua.", "img": "data:image/webp;base64,"}, {"id": 128, "t": "Detection, segmentation & face", "a": "C", "n": 4, "w": 1200, "h": 282, "x": "64 điểm × (x, y) = 128 + 1 (có mặt hay không) = 129.", "tip": "2 × số điểm + 1.", "img": "data:image/webp;base64,"}, {"id": 129, "t": "Detection, segmentation & face", "a": "A", "n": 4, "w": 1164, "h": 354, "x": "Sliding windows chạy CNN trên rất nhiều cửa sổ nên chi phí tính toán rất cao.", "tip": "Nhiều cửa sổ = rất chậm.", "img": "data:image/webp;base64,"}, {"id": 130, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1200, "h": 288, "x": "FC 400 unit được thay bằng 400 filter 5×5 cho output 1×1×400.", "tip": "FC = conv có filter bằng cả input.", "img": "data:image/webp;base64,"}, {"id": 131, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1200, "h": 265, "x": "(16 − 14)/2 + 1 = 2 → 2×2×4, mỗi ô ứng với một cửa sổ.", "tip": "Conv sliding window chạy một lượt.", "img": "data:image/webp;base64,"}, {"id": 132, "t": "Detection, segmentation & face", "a": "C", "n": 4, "w": 1148, "h": 374, "x": "Ô chứa trung điểm của vật thể chịu trách nhiệm phát hiện nó.", "tip": "YOLO: theo trung điểm.", "img": "data:image/webp;base64,"}, {"id": 133, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1200, "h": 337, "x": "b_h, b_w tính theo tỉ lệ kích thước ô nên có thể lớn hơn 1.", "tip": "Vật to hơn ô → > 1.", "img": "data:image/webp;base64,"}, {"id": 134, "t": "Detection, segmentation & face", "a": "A", "n": 4, "w": 1200, "h": 305, "x": "Quy ước: IoU ≥ 0.5 là đúng.", "tip": "Mốc 0.5.", "img": "data:image/webp;base64,"}, {"id": 135, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1200, "h": 281, "x": "Bước đầu NMS: bỏ mọi box có p_c ≤ 0.6.", "tip": "Lọc box yếu trước.", "img": "data:image/webp;base64,"}, {"id": 136, "t": "Detection, segmentation & face", "a": "C", "n": 4, "w": 1200, "h": 289, "x": "Sau khi chọn box có p_c cao nhất, bỏ các box còn lại có IoU ≥ 0.5 với nó.", "tip": "Trùng nhiều → bỏ.", "img": "data:image/webp;base64,"}, {"id": 137, "t": "Detection, segmentation & face", "a": "A", "n": 4, "w": 1200, "h": 368, "x": "Anchor box xử lý trường hợp hai vật có trung điểm rơi vào cùng một ô.", "tip": "Anchor = nhiều vật một ô.", "img": "data:image/webp;base64,"}, {"id": 138, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1200, "h": 275, "x": "Mỗi anchor có 5 + 3 = 8 giá trị; 2 anchor → 16 → 3×3×16.", "tip": "(5 + số lớp) × số anchor.", "img": "data:image/webp;base64,"}, {"id": 139, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1120, "h": 444, "x": "Chọn hình dạng anchor bằng tay (5–10 hình) hoặc dùng K-means.", "tip": "Tay hoặc K-means.", "img": "data:image/webp;base64,"}, {"id": 140, "t": "Detection, segmentation & face", "a": "C", "n": 4, "w": 1200, "h": 334, "x": "Faster R-CNN dùng mạng tích chập để đề xuất vùng (RPN).", "tip": "Faster = conv đề xuất vùng.", "img": "data:image/webp;base64,"}, {"id": 141, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1066, "h": 460, "x": "Semantic segmentation gán nhãn cho từng điểm ảnh.", "tip": "Segmentation = theo pixel.", "img": "data:image/webp;base64,"}, {"id": 142, "t": "Detection, segmentation & face", "a": "A", "n": 4, "w": 1200, "h": 228, "x": "Theo ví dụ trong khoá học, input 2×2, filter 3×3, p = 1, s = 2 cho output 4×4 (phần padding bị bỏ khi ghép).", "tip": "Transpose conv phóng to ảnh.", "img": "data:image/webp;base64,"}, {"id": 143, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1200, "h": 272, "x": "Skip connection của U-Net ghép ngữ cảnh mức cao với chi tiết mức thấp để gán nhãn pixel chính xác.", "tip": "U-Net: nối tắt encoder sang decoder.", "img": "data:image/webp;base64,"}, {"id": 144, "t": "Detection, segmentation & face", "a": "C", "n": 4, "w": 1200, "h": 303, "x": "Verification là 1:1 (có phải người này không); recognition là 1:K.", "tip": "Verify 1:1, recognize 1:K.", "img": "data:image/webp;base64,"}, {"id": 145, "t": "Detection, segmentation & face", "a": "D", "n": 4, "w": 1200, "h": 277, "x": "One-shot: học hàm tương đồng d(img1, img2) rồi so với ngưỡng τ.", "tip": "So khoảng cách, không train lại.", "img": "data:image/webp;base64,"}, {"id": 146, "t": "Detection, segmentation & face", "a": "A", "n": 4, "w": 1200, "h": 237, "x": "Margin α chống nghiệm tầm thường (mọi encoding bằng nhau) và đẩy cặp A–P, A–N cách xa.", "tip": "α = khoảng an toàn.", "img": "data:image/webp;base64,"}, {"id": 147, "t": "Detection, segmentation & face", "a": "B", "n": 4, "w": 1200, "h": 300, "x": "Gram matrix đo tương quan giữa activation các kênh trong một lớp.", "tip": "Style = tương quan kênh.", "img": "data:image/webp;base64,"}, {"id": 149, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 272, "x": "Câu dài ngắn khác nhau và mạng chuẩn không chia sẻ đặc trưng giữa các vị trí.", "tip": "Độ dài thay đổi → cần RNN.", "img": "data:image/webp;base64,"}, {"id": 150, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "x⟨3⟩ là từ thứ 3: 'and' (Harry=1, Potter=2).", "tip": "Đếm từ 1.", "img": "data:image/webp;base64,"}, {"id": 151, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 365, "x": "Từ ngoài từ điển được thay bằng token ⟨UNK⟩.", "tip": "UNK = unknown.", "img": "data:image/webp;base64,"}, {"id": 152, "t": "RNN, GRU & LSTM", "a": "B", "n": 4, "w": 1200, "h": 425, "x": "a⟨0⟩ thường khởi tạo là vector 0.", "tip": "Bắt đầu từ 0.", "img": "data:image/webp;base64,"}, {"id": 153, "t": "RNN, GRU & LSTM", "a": "A", "n": 4, "w": 1200, "h": 352, "x": "W_aa, W_ax, W_ya dùng chung cho mọi bước thời gian.", "tip": "RNN chia sẻ tham số theo thời gian.", "img": "data:image/webp;base64,"}, {"id": 154, "t": "RNN, GRU & LSTM", "a": "C", "n": 4, "w": 1200, "h": 303, "x": "a⟨t⟩ thường dùng tanh (đôi khi ReLU).", "tip": "Ẩn: tanh; output: sigmoid/softmax.", "img": "data:image/webp;base64,"}, {"id": 155, "t": "RNN, GRU & LSTM", "a": "D", "n": 4, "w": 1200, "h": 231, "x": "Ghép ngang 100×100 và 100×10.000 → 100×10.100.", "tip": "Ghép cột: cộng số cột.", "img": "data:image/webp;base64,"}, {"id": 156, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 255, "x": "Deep learning cất cánh nhờ dữ liệu lớn, sức tính toán (GPU) và cải tiến thuật toán.", "tip": "Data + Compute + Algorithms.", "img": "data:image/webp;base64,"}, {"id": 157, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 411, "x": "ReLU(z) = max(0, z).", "tip": "Âm thành 0.", "img": "data:image/webp;base64,"}, {"id": 158, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 286, "x": "Lớp ẩn tự học đặc trưng như quy mô gia đình, khả năng đi bộ, chất lượng trường học.", "tip": "Hidden unit tự học feature.", "img": "data:image/webp;base64,"}, {"id": 159, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 252, "x": "Gắn thẻ ảnh dùng CNN.", "tip": "Ảnh → CNN.", "img": "data:image/webp;base64,"}, {"id": 160, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 243, "x": "Giọng nói, dịch máy là dữ liệu chuỗi → RNN.", "tip": "Chuỗi → RNN.", "img": "data:image/webp;base64,"}, {"id": 161, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 292, "x": "Lái xe tự động kết hợp ảnh + radar → kiến trúc tuỳ biến/lai.", "tip": "Đa nguồn → hybrid.", "img": "data:image/webp;base64,"}, {"id": 162, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 305, "x": "Structured data: dữ liệu bảng, mỗi cột có ý nghĩa rõ.", "tip": "Structured = bảng.", "img": "data:image/webp;base64,"}, {"id": 163, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 467, "x": "Ảnh, âm thanh, văn bản là dữ liệu phi cấu trúc.", "tip": "Unstructured = ảnh, tiếng, chữ.", "img": "data:image/webp;base64,"}, {"id": 164, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 283, "x": "Thuật toán truyền thống chững lại khi dữ liệu tăng, mạng nơ-ron lớn vẫn tiếp tục cải thiện.", "tip": "NN lớn tận dụng big data.", "img": "data:image/webp;base64,"}, {"id": 165, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 270, "x": "Sigmoid có vùng gradient ≈ 0 làm học chậm; ReLU không bị ở vùng dương.", "tip": "Sigmoid bão hoà → chậm.", "img": "data:image/webp;base64,"}, {"id": 166, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 261, "x": "Vòng Idea → Code → Experiment nhanh giúp thử và cải tiến ý tưởng nhanh hơn nhiều.", "tip": "Lặp nhanh = tiến nhanh.", "img": "data:image/webp;base64,"}, {"id": 167, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 298, "x": "64 × 64 × 3 = 12.288.", "tip": "Cao × rộng × 3 kênh.", "img": "data:image/webp;base64,"}, {"id": 168, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 342, "x": "X có shape (n_x, m): mỗi cột là một mẫu.", "tip": "Mẫu xếp theo cột.", "img": "data:image/webp;base64,"}, {"id": 169, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 288, "x": "Y có shape (1, m).", "tip": "Một hàng nhãn.", "img": "data:image/webp;base64,"}, {"id": 170, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 449, "x": "ŷ = P(y = 1 | x).", "tip": "ŷ là xác suất.", "img": "data:image/webp;base64,"}, {"id": 171, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 319, "x": "Squared error với sigmoid làm bài toán tối ưu không lồi (nhiều cực tiểu địa phương).", "tip": "Logistic dùng cross-entropy để lồi.", "img": "data:image/webp;base64,"}, {"id": 172, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 385, "x": "L = −(y log ŷ + (1 − y) log(1 − ŷ)).", "tip": "Binary cross-entropy.", "img": "data:image/webp;base64,"}, {"id": 173, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 335, "x": "Tối thiểu J tương đương ước lượng hợp lý cực đại (MLE) với giả định i.i.d.", "tip": "Min loss = max likelihood.", "img": "data:image/webp;base64,"}, {"id": 174, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 263, "x": "Hàm chi phí J của logistic regression lồi nên chỉ có một cực tiểu toàn cục.", "tip": "Lồi → 1 cực tiểu.", "img": "data:image/webp;base64,"}, {"id": 175, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1053, "h": 438, "x": "f'(a) = 2a = 4 tại a = 2.", "tip": "Đạo hàm a² là 2a.", "img": "data:image/webp;base64,"}, {"id": 176, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1196, "h": 467, "x": "f'(a) = 1/a = 0.5 tại a = 2.", "tip": "Đạo hàm ln a là 1/a.", "img": "data:image/webp;base64,"}, {"id": 177, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1109, "h": 556, "x": "J = 3a + 3bc → dJ/db = 3c.", "tip": "Coi a, c là hằng.", "img": "data:image/webp;base64,"}, {"id": 178, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 307, "x": "dvar = đạo hàm của J theo var.", "tip": "d-gì cũng là dJ/d-gì.", "img": "data:image/webp;base64,"}, {"id": 179, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1152, "h": 453, "x": "dz = a − y.", "tip": "Dự đoán trừ thực tế.", "img": "data:image/webp;base64,"}, {"id": 180, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1083, "h": 492, "x": "dw₁ = x₁ · dz.", "tip": "dw = x · dz.", "img": "data:image/webp;base64,"}, {"id": 181, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 253, "x": "Cài bằng vòng lặp cần hai vòng (m mẫu, n đặc trưng) nên chậm.", "tip": "Vector hoá bỏ vòng lặp.", "img": "data:image/webp;base64,"}, {"id": 182, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 236, "x": "np.dot ~1.5 ms so với ~500 ms vòng for (~300 lần).", "tip": "Vectorize nhanh hàng trăm lần.", "img": "data:image/webp;base64,"}, {"id": 183, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 346, "x": "Hàm NumPy dùng lệnh song song SIMD trên CPU/GPU.", "tip": "SIMD = một lệnh nhiều dữ liệu.", "img": "data:image/webp;base64,"}, {"id": 184, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 378, "x": "dw = (1/m) · np.dot(X, dZ.T).", "tip": "Nhớ chia m và chuyển vị dZ.", "img": "data:image/webp;base64,"}, {"id": 185, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 288, "x": "Vòng lặp qua các lần gradient descent không bỏ được.", "tip": "Iteration loop luôn còn.", "img": "data:image/webp;base64,"}, {"id": 186, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 421, "x": "(1, n) được nhân bản thành m hàng để cộng với (m, n).", "tip": "Broadcast kéo giãn chiều 1.", "img": "data:image/webp;base64,"}, {"id": 187, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1018, "h": 482, "x": "100 được broadcast: [101 102 103 104].", "tip": "Số vô hướng cộng từng phần tử.", "img": "data:image/webp;base64,"}, {"id": 188, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 252, "x": "Dùng randn(5, 1) thay randn(5) (rank-1) và thêm assert shape.", "tip": "Tránh shape (n,).", "img": "data:image/webp;base64,"}, {"id": 189, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 305, "x": "Tổng calo mỗi món = cộng theo cột: A.sum(axis=0).", "tip": "axis=0 = theo cột (dọc).", "img": "data:image/webp;base64,"}, {"id": 190, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 264, "x": "Mạng 1 lớp ẩn + 1 lớp ra gọi là mạng 2 lớp (không đếm input).", "tip": "Không đếm input layer.", "img": "data:image/webp;base64,"}, {"id": 191, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 393, "x": "Giá trị lớp ẩn không quan sát được trong tập huấn luyện.", "tip": "Hidden = không thấy nhãn.", "img": "data:image/webp;base64,"}, {"id": 192, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1197, "h": 394, "x": "W^[1] có shape (n^[1], n^[0]) = (4, 3).", "tip": "W^[l]: (lớp này, lớp trước).", "img": "data:image/webp;base64,"}, {"id": 193, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 306, "x": "3·4 + 4 + 4·1 + 1 = 21.", "tip": "Trọng số + bias mỗi lớp.", "img": "data:image/webp;base64,"}, {"id": 194, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 275, "x": "Ngang = mẫu huấn luyện, dọc = hidden unit.", "tip": "Cột = mẫu.", "img": "data:image/webp;base64,"}, {"id": 195, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 362, "x": "tanh có output trung bình gần 0 nên lớp sau học dễ hơn.", "tip": "tanh centered at 0.", "img": "data:image/webp;base64,"}, {"id": 196, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 304, "x": "σ'(z) = a(1 − a).", "tip": "Sigmoid: a(1 − a).", "img": "data:image/webp;base64,"}, {"id": 197, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1125, "h": 379, "x": "tanh'(z) = 1 − a².", "tip": "tanh: 1 − a².", "img": "data:image/webp;base64,"}, {"id": 198, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 479, "x": "Leaky ReLU cho gradient nhỏ khi z < 0, tránh neuron chết.", "tip": "Leaky = rỉ chút gradient.", "img": "data:image/webp;base64,"}, {"id": 199, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 361, "x": "ReLU là lựa chọn mặc định cho lớp ẩn.", "tip": "Không chắc → ReLU.", "img": "data:image/webp;base64,"}, {"id": 200, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 294, "x": "Toàn linear thì cả mạng vẫn là hàm tuyến tính của input.", "tip": "Cần phi tuyến mới sâu được.", "img": "data:image/webp;base64,"}, {"id": 201, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 276, "x": "Linear chấp nhận được ở lớp output bài hồi quy (giá nhà).", "tip": "Hồi quy → output linear.", "img": "data:image/webp;base64,"}, {"id": 202, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1121, "h": 334, "x": "dZ1 = (W2ᵀ dZ2) * g1'(Z1).", "tip": "Lan ngược qua W rồi nhân đạo hàm activation.", "img": "data:image/webp;base64,"}, {"id": 203, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 268, "x": "keepdims=True giữ shape (n, 1) thay vì mảng rank-1.", "tip": "Giữ chiều để broadcast đúng.", "img": "data:image/webp;base64,"}, {"id": 204, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 245, "x": "W = 0 → đối xứng: mọi unit ẩn giống nhau, cập nhật như nhau.", "tip": "Phải random W.", "img": "data:image/webp;base64,"}, {"id": 205, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 312, "x": "Nhân 0.01 để z nhỏ, tránh vùng bão hoà của sigmoid/tanh.", "tip": "W nhỏ → gradient lớn.", "img": "data:image/webp;base64,"}, {"id": 206, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 361, "x": "b = 0 không gây đối xứng vì W đã random.", "tip": "b = 0 thoải mái.", "img": "data:image/webp;base64,"}, {"id": 207, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 389, "x": "L là số lớp, không tính input.", "tip": "L = số lớp.", "img": "data:image/webp;base64,"}, {"id": 208, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 647, "h": 414, "x": "W^[l]: (n^[l], n^[l−1]).", "tip": "(ra, vào).", "img": "data:image/webp;base64,"}, {"id": 209, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 572, "h": 378, "x": "b^[l]: (n^[l], 1).", "tip": "Mỗi unit một bias.", "img": "data:image/webp;base64,"}, {"id": 210, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 318, "x": "n^[1] = 3, n^[0] = 2 → W^[1] (3, 2).", "tip": "(n^[1], n^[0]).", "img": "data:image/webp;base64,"}, {"id": 211, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 349, "x": "Z^[l], A^[l]: (n^[l], m).", "tip": "Có m thì m ở cột.", "img": "data:image/webp;base64,"}, {"id": 212, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 234, "x": "Vòng lặp qua các lớp không bỏ được.", "tip": "Lặp qua lớp là bắt buộc.", "img": "data:image/webp;base64,"}, {"id": 213, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 285, "x": "Lớp sâu học dần: cạnh → bộ phận khuôn mặt → cả khuôn mặt.", "tip": "Đơn giản → phức tạp.", "img": "data:image/webp;base64,"}, {"id": 214, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 254, "x": "XOR n bit: mạng sâu cần O(log n) lớp, mạng nông cần ~2^n unit.", "tip": "Sâu tiết kiệm hơn rộng.", "img": "data:image/webp;base64,"}, {"id": 215, "t": "Neural Networks cơ bản", "a": "D", "n": 4, "w": 1200, "h": 365, "x": "Cache lưu Z^[l] (và W^[l], b^[l]) để dùng khi lan truyền ngược.", "tip": "Cache cho backward.", "img": "data:image/webp;base64,"}, {"id": 216, "t": "Neural Networks cơ bản", "a": "A", "n": 4, "w": 1200, "h": 254, "x": "dA^[L] = −Y/A + (1 − Y)/(1 − A).", "tip": "Đạo hàm cross-entropy theo A.", "img": "data:image/webp;base64,"}, {"id": 217, "t": "Neural Networks cơ bản", "a": "C", "n": 4, "w": 1200, "h": 329, "x": "W và b là tham số; learning rate, số lớp, activation là siêu tham số.", "tip": "Học được = parameter.", "img": "data:image/webp;base64,"}, {"id": 218, "t": "Neural Networks cơ bản", "a": "B", "n": 4, "w": 1200, "h": 234, "x": "Phép so sánh với não chỉ là lỏng lẻo; chưa ai biết não có dùng backprop không.", "tip": "Đừng tin 'giống não'.", "img": "data:image/webp;base64,"}, {"id": 220, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 291, "x": "Dev set dùng để so sánh và chọn mô hình.", "tip": "Dev = chọn mô hình; test = đánh giá cuối.", "img": "data:image/webp;base64,"}, {"id": 221, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 310, "x": "Dữ liệu ~1 triệu mẫu → chia 98/1/1.", "tip": "Big data: dev/test chỉ cần ~1%.", "img": "data:image/webp;base64,"}, {"id": 222, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 270, "x": "Dev và test phải cùng phân phối.", "tip": "Dev ≡ test.", "img": "data:image/webp;base64,"}, {"id": 223, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 253, "x": "Train 1%, dev 11% → variance cao.", "tip": "Train tốt, dev tệ = variance.", "img": "data:image/webp;base64,"}, {"id": 224, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 251, "x": "Train 15%, dev 16% → bias cao.", "tip": "Train tệ, dev gần train = bias.", "img": "data:image/webp;base64,"}, {"id": 225, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 320, "x": "Train 15% (bias) và dev 30% (variance) → cả hai cao.", "tip": "Cả hai khoảng cách đều lớn.", "img": "data:image/webp;base64,"}, {"id": 226, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 311, "x": "Bias cao: mạng to hơn hoặc train lâu hơn.", "tip": "Bias → to hơn.", "img": "data:image/webp;base64,"}, {"id": 227, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1198, "h": 342, "x": "Variance cao: thêm dữ liệu hoặc regularization.", "tip": "Variance → data/regularize.", "img": "data:image/webp;base64,"}, {"id": 228, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 379, "x": "Mỗi bước W nhân (1 − αλ/m) nên co lại → weight decay.", "tip": "L2 làm W teo dần.", "img": "data:image/webp;base64,"}, {"id": 229, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 344, "x": "L1 đẩy nhiều trọng số về đúng 0 → mô hình thưa.", "tip": "L1 = sparse.", "img": "data:image/webp;base64,"}, {"id": 230, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 383, "x": "λ chọn bằng dev set.", "tip": "Siêu tham số chọn trên dev.", "img": "data:image/webp;base64,"}, {"id": 231, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1189, "h": 376, "x": "Chia keep_prob để giữ kỳ vọng a3 không đổi.", "tip": "Inverted = bù lại phần bị tắt.", "img": "data:image/webp;base64,"}, {"id": 232, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 349, "x": "Không dùng dropout khi test để dự đoán không ngẫu nhiên.", "tip": "Test: tắt dropout.", "img": "data:image/webp;base64,"}, {"id": 233, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1145, "h": 359, "x": "Lớp nhiều tham số dễ overfit nên keep_prob thấp hơn.", "tip": "Lớp to → dropout nhiều.", "img": "data:image/webp;base64,"}, {"id": 234, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 257, "x": "Với dropout, J không còn định nghĩa rõ nên khó vẽ J để kiểm tra giảm dần.", "tip": "Debug: tắt dropout trước.", "img": "data:image/webp;base64,"}, {"id": 235, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 331, "x": "Early stopping trộn việc tối ưu J với chống overfit vào một núm.", "tip": "Không trực giao.", "img": "data:image/webp;base64,"}, {"id": 236, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 375, "x": "Chuẩn hoá test bằng μ, σ tính trên tập train.", "tip": "Dùng chung μ, σ của train.", "img": "data:image/webp;base64,"}, {"id": 237, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 243, "x": "Chuẩn hoá làm hàm chi phí tròn hơn, dùng được learning rate lớn hơn.", "tip": "Tròn → đi thẳng xuống.", "img": "data:image/webp;base64,"}, {"id": 238, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 254, "x": "W ≈ 1.5·I thì activation tăng như 1.5^L (exploding).", "tip": "> 1 thì nổ, < 1 thì tắt.", "img": "data:image/webp;base64,"}, {"id": 239, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 350, "x": "He init cho ReLU: variance 2/n^[l−1].", "tip": "ReLU → 2/n.", "img": "data:image/webp;base64,"}, {"id": 240, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 235, "x": "Xavier 1/n^[l−1] thường đi với tanh.", "tip": "tanh → Xavier.", "img": "data:image/webp;base64,"}, {"id": 241, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 245, "x": "Sai phân hai phía có sai số O(ε²).", "tip": "Hai phía chính xác hơn một phía.", "img": "data:image/webp;base64,"}, {"id": 242, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 234, "x": "Chênh 10⁻³ là lớn → rất có thể có bug.", "tip": "10⁻⁷ tốt, 10⁻⁵ xem lại, 10⁻³ lỗi.", "img": "data:image/webp;base64,"}, {"id": 243, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 380, "x": "Tắt dropout (keep_prob = 1) khi gradient checking.", "tip": "Grad check không đi với dropout.", "img": "data:image/webp;base64,"}, {"id": 244, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 248, "x": "SGD cập nhật sau mỗi mẫu, rất nhiễu và mất lợi thế vector hoá.", "tip": "Batch size = 1.", "img": "data:image/webp;base64,"}, {"id": 245, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 289, "x": "2000/4 = 500 lần mỗi epoch × 10 = 5000.", "tip": "(m / batch) × epoch.", "img": "data:image/webp;base64,"}, {"id": 246, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 384, "x": "Tập nhỏ (m < 2000) thì dùng batch GD luôn.", "tip": "Ít dữ liệu → batch.", "img": "data:image/webp;base64,"}, {"id": 247, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 272, "x": "β = 0.9 trung bình khoảng 1/(1 − β) = 10 giá trị gần nhất.", "tip": "≈ 1/(1 − β).", "img": "data:image/webp;base64,"}, {"id": 248, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 273, "x": "V₀ = 0 làm ước lượng ban đầu quá thấp; bias correction sửa điều đó.", "tip": "Sửa khởi động lạnh.", "img": "data:image/webp;base64,"}, {"id": 249, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 264, "x": "Momentum làm dao động dọc triệt tiêu, tiến ngang tích luỹ.", "tip": "Lắc ngang triệt tiêu, đi thẳng cộng dồn.", "img": "data:image/webp;base64,"}, {"id": 250, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 423, "x": "RMSprop: W := W − α · dW / (√S_dW + ε).", "tip": "Chia cho căn bình phương trung bình.", "img": "data:image/webp;base64,"}, {"id": 251, "t": "Regularization & tối ưu hoá", "a": "B", "n": 4, "w": 1200, "h": 304, "x": "Adam mặc định: β₁ = 0.9, β₂ = 0.999, ε = 10⁻⁸.", "tip": "0.9 / 0.999 / 1e−8.", "img": "data:image/webp;base64,"}, {"id": 252, "t": "Regularization & tối ưu hoá", "a": "D", "n": 4, "w": 1200, "h": 262, "x": "α = 0.2 / (1 + 1·1) = 0.1.", "tip": "Thế epoch = 1.", "img": "data:image/webp;base64,"}, {"id": 253, "t": "Regularization & tối ưu hoá", "a": "C", "n": 4, "w": 1200, "h": 303, "x": "Trong không gian nhiều chiều, điểm có gradient 0 chủ yếu là điểm yên ngựa.", "tip": "Ít lo local optima, lo plateau.", "img": "data:image/webp;base64,"}, {"id": 254, "t": "Regularization & tối ưu hoá", "a": "A", "n": 4, "w": 1200, "h": 320, "x": "Learning rate α là siêu tham số quan trọng nhất.", "tip": "Ưu tiên chỉnh α.", "img": "data:image/webp;base64,"}]};
